1	import React, { useState, useRef } from 'react';
2	import { uploadImagem } from '../../services/restauranteService';
3	import Icon from '../AppIcon';
4	
5	const MAX_MB = 5;
6	const ACCEPT = 'image/jpeg,image/jpg,image/png,image/webp,image/gif';
7	
8	/**
9	 * Props:
10	 *  value      — URL atual da imagem
11	 *  onChange   — (url: string) => void
12	 *  folder     — subpasta no bucket ('logos' | 'banners' | 'carrossel' | 'fundos')
13	 *  aspect     — proporção do preview: 'square' | 'wide' | 'banner'
14	 *  placeholder — texto no input URL
15	 */
16	const ImageUpload = ({ value, onChange, folder = 'geral', aspect = 'wide', placeholder = 'https://...' }) => {
17	  const [tab, setTab] = useState('upload');
18	  const [urlInput, setUrlInput] = useState('');
19	  const [uploading, setUploading] = useState(false);
20	  const [progress, setProgress] = useState(0);
21	  const [erro, setErro] = useState(null);
22	  const [dragOver, setDragOver] = useState(false);
23	  const fileRef = useRef(null);
24	
25	  const previewH = aspect === 'square' ? 'h-32 w-32' : aspect === 'banner' ? 'h-32 w-full' : 'h-24 w-full';
26	
27	  const upload = async (file) => {
28	    setErro(null);
29	    if (!file.type.startsWith('image/')) { setErro('Apenas imagens (JPG, PNG, WEBP)'); return; }
30	    if (file.size > MAX_MB * 1024 * 1024) { setErro(`Máximo ${MAX_MB}MB`); return; }
31	
32	    setUploading(true);
33	    setProgress(20);
34	    try {
35	      setProgress(50);
36	      const result = await uploadImagem(file, folder);
37	      setProgress(100);
38	      onChange(result.url);
39	    } catch (e) {
40	      setErro(e.message ?? 'Erro no upload');
41	    } finally {
42	      setUploading(false);
43	      setProgress(0);
44	      if (fileRef.current) fileRef.current.value = '';
45	    }
46	  };
47	
