1	import React from 'react';
2	import { AnimatePresence, motion } from 'framer-motion';
3	import { useNavigate } from 'react-router-dom';
4	import Icon from '../AppIcon';
5	
6	// Menu lateral só pra desktop/telas grandes (md+) — substitui a barra horizontal de
7	// botões que ficava poluída com muitos links. Mobile continua com o próprio menu de cada
8	// página (hamburger + lista já existente), este componente nunca renderiza abaixo de md.
9	const RestauranteSidebar = ({ open, onClose, links, activePath, pendentesMotoboy = 0, slugLoja, onSair, isFavorito, onToggleFavorito }) => {
10	  const navigate = useNavigate();
11	  const ir = (path) => { navigate(path); onClose(); };
12	
13	  return (
14	    <AnimatePresence>
15	      {open && (
16	        <div className="hidden md:block">
17	          <motion.div
18	            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
19	            className="fixed inset-0 bg-black/40 z-40"
20	            onClick={onClose}
21	          />
22	          <motion.div
23	            initial={{ x: -320, opacity: 0 }} animate={{ x: 0, opacity: 1 }} exit={{ x: -320, opacity: 0 }}
24	            transition={{ type: 'tween', duration: 0.2 }}
25	            className="fixed top-0 left-0 h-full w-72 bg-white z-50 shadow-2xl flex flex-col"
26	          >
27	            <div className="flex items-center justify-between px-5 py-4 border-b border-[#E4E4E7]">
28	              <p className="font-bold text-[#18181B]">Menu</p>
29	              <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-[#F4F4F5] text-[#71717A]">
30	                <Icon name="X" size={18} />
31	              </button>
32	            </div>
33	            <nav className="flex-1 overflow-y-auto px-3 py-3 flex flex-col gap-1">
34	              {links.map((l) => (
35	                <div key={l.path} className={`relative flex items-center rounded-xl transition-colors ${
36	                    l.path === activePath ? 'text-white bg-[#FF441F]' : 'text-[#27272A] hover:bg-[#F4F4F5]'
37	                  }`}>
38	                  <button onClick={() => ir(l.path)}
39	                    className="flex-1 flex items-center justify-between text-left pl-4 pr-2 py-2.5 text-sm font-semibold min-w-0">
40	                    {l.label}
41	                    {l.path === '/restaurante/motoboys' && pendentesMotoboy > 0 && (
42	                      <span className="min-w-[18px] h-[18px] px-1 flex items-center justify-center bg-red-500 text-white text-[10px] font-bold rounded-full ml-2">
43	                        {pendentesMotoboy}
44	                      </span>
45	                    )}
46	                  </button>
47	                  {onToggleFavorito && (
48	                    <button onClick={() => onToggleFavorito(l.path)}
49	                      className={`p-2 mr-1 rounded-lg flex-shrink-0 ${l.path === activePath ? 'hover:bg-white/20' : 'hover:bg-[#E4E4E7]'}`}
50	                      title={isFavorito?.(l.path) ? 'Remover dos favoritos' : 'Adicionar aos favoritos'}>
51	                      <Icon name="Star" size={15} className={isFavorito?.(l.path) ? 'fill-current' : ''} />
52	                    </button>
53	                  )}
54	                </div>
55	              ))}
