21	  delivered:          'bg-green-100 text-green-800 border-green-200',
22	  canceled:           'bg-red-100 text-red-800 border-red-200',
23	};
24	
25	const STATUS_LABEL = {
26	  pending: 'Recebido', confirmed: 'Aguardando Preparo', preparing: 'Em Preparo',
27	  ready: 'Pronto', motoboy_collecting: 'Motoboy coletando',
28	  out_for_delivery: 'Em entrega', delivered: 'Entregue', canceled: 'Cancelado',
29	};
30	
31	const PROXIMOS    = { pending: 'confirmed', confirmed: 'preparing', preparing: 'ready', ready: 'motoboy_collecting', motoboy_collecting: 'out_for_delivery', out_for_delivery: 'delivered' };
32	const ANTERIORES  = { confirmed: 'pending', preparing: 'confirmed', ready: 'preparing', motoboy_collecting: 'ready', out_for_delivery: 'motoboy_collecting', delivered: 'out_for_delivery' };
33	
34	const timeAgo = (iso) => {
35	  if (!iso) return null;
36	  const diff = Math.floor((Date.now() - new Date(iso)) / 1000);
37	  if (diff < 60) return `há ${diff}s`;
38	  if (diff < 3600) return `há ${Math.floor(diff / 60)}min`;
39	  return `há ${Math.floor(diff / 3600)}h`;
