44	);
45	
46	const SectionTitle = ({ icon, label, color = 'text-[#FF441F]' }) => (
47	  <div className="px-4 py-3 border-b border-[#F4F4F5] flex items-center gap-2">
48	    <Icon name={icon} size={14} className={color} />
49	    <p className="text-xs font-bold text-[#71717A] uppercase tracking-wide">{label}</p>
