51	);
52	
53	const PedidoDetalhe = ({
54	  detalhe, onAvancar, onReimprimir, atualizando, onClose, onDetalheMudou, saldoCaixa = 0,
55	  motoboys = [], onAtribuir, onEntregarProprio,
56	}) => {
57	  const [trocoInput, setTrocoInput] = useState('');
58	  const [salvandoTroco, setSalvandoTroco] = useState(false);
59	  const [zerrandoFrete, setZerrandoFrete] = useState(false);
60	  const [showCancelar, setShowCancelar] = useState(false);
