228	            </div>
229	          ) : (
230	            <p className="text-xs text-[#A1A1AA] italic">Dados do cliente não disponíveis</p>
231	          )}
232	        </div>
233	      </Section>
234	
235	      {/* Motoboy / Rastreamento */}
236	      {(motoboy || pedido.motoboy_id) && (
237	        <Section>
238	          <SectionTitle icon="Bike" label="Rastreamento da entrega" color="text-indigo-600" />
239	          <div className="p-4 space-y-3">
240	            <div className="flex items-center justify-between gap-3">
241	              <div>
242	                <p className="text-sm font-bold text-[#18181B]">{motoboy?.name ?? 'Motoboy atribuído'}</p>
243	                {motoboy?.phone && <p className="text-xs text-[#71717A]">{motoboy.phone}</p>}
244	              </div>
245	              {motoboy?.phone && (
246	                <a href={`tel:${motoboy.phone}`}
247	                  className="w-9 h-9 bg-indigo-50 border border-indigo-200 rounded-xl flex items-center justify-center hover:bg-indigo-100 transition-colors flex-shrink-0">
248	                  <Icon name="Phone" size={14} className="text-indigo-600" />
249	                </a>
250	              )}
251	            </div>
252	
253	            {pedido.motoboy_lat && pedido.motoboy_lng ? (
254	              <div className="bg-indigo-50 border border-indigo-100 rounded-xl p-3">
255	                <div className="flex items-center gap-2 mb-2">
256	                  <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse flex-shrink-0" />
257	                  <p className="text-xs font-semibold text-indigo-800">
258	                    GPS ativo · {timeAgo(pedido.motoboy_location_at) ?? 'agora'}
259	                  </p>
260	                </div>
261	                <p className="text-[10px] text-indigo-500 mb-2 font-mono">
262	                  {pedido.motoboy_lat.toFixed(5)}, {pedido.motoboy_lng.toFixed(5)}
263	                </p>
264	                <div className="flex gap-2">
265	                  <a href={mapsMotoboyUrl} target="_blank" rel="noopener noreferrer"
266	                    className="flex-1 flex items-center justify-center gap-1.5 py-2 bg-indigo-600 hover:bg-indigo-700 text-white font-bold text-xs rounded-lg transition-colors">
267	                    <Icon name="MapPin" size={12} /> Ver localização
