271	                      className="flex-1 flex items-center justify-center gap-1.5 py-2 bg-white border border-indigo-200 text-indigo-700 font-bold text-xs rounded-lg hover:bg-indigo-50 transition-colors">
272	                      <Icon name="Route" size={12} /> Ver rota
273	                    </a>
274	                  )}
275	                </div>
276	              </div>
277	            ) : (
278	              <div className="bg-[#F4F4F5] rounded-xl p-3 flex items-center gap-2">
279	                <Icon name="Signal" size={14} className="text-[#A1A1AA]" />
280	                <p className="text-xs text-[#71717A]">Aguardando sinal GPS do motoboy</p>
281	              </div>
282	            )}
283	          </div>
284	        </Section>
285	      )}
286	
287	      {/* Sem motoboy atribuído ainda — atribuir ou entregar pela própria loja */}
288	      {!isCanceled && !pedido.motoboy_id && ['ready', 'out_for_delivery'].includes(pedido.status) && (
289	        <Section>
290	          <SectionTitle icon="Truck" label="Entrega" color="text-indigo-600" />
291	          <div className="p-4 space-y-3">
292	            {motoboys.length > 0 && (
293	              <div className="flex gap-2">
294	                <select
295	                  value={motoboySelecionado}
296	                  onChange={(e) => setMotoboySelecionado(e.target.value)}
297	                  className="flex-1 border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-indigo-400"
298	                >
299	                  <option value="">Atribuir a um motoboy...</option>
300	                  {motoboys.map((m) => (
301	                    <option key={m.id} value={m.id}>{m.name}{m.phone ? ` · ${m.phone}` : ''}</option>
302	                  ))}
303	                </select>
304	                <button
305	                  onClick={handleAtribuir}
306	                  disabled={!motoboySelecionado || atribuindo}
307	                  className="flex-shrink-0 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-bold rounded-xl disabled:opacity-50 transition-colors"
308	                >
309	                  {atribuindo ? '...' : 'Atribuir'}
310	                </button>
311	              </div>
312	            )}
313	            <button
314	              onClick={handleEntregarProprio}
315	              disabled={entregandoProprio}
316	              className="w-full py-2.5 border-2 border-green-300 bg-green-50 text-green-700 text-sm font-bold rounded-xl hover:bg-green-100 disabled:opacity-50 transition-colors flex items-center justify-center gap-2"
317	            >
318	              <Icon name="Store" size={15} />
319	              {entregandoProprio ? 'Confirmando...' : 'Marcar como entregue (entrega própria)'}
320	            </button>
321	          </div>
322	        </Section>
323	      )}
324	
325	      {/* Ocorrência */}
326	      {pedido.delivery_occurrence && pedido.delivery_notes && (
327	        <div className={`rounded-2xl border p-4 ${
328	          pedido.delivery_occurrence === 'cancelada'
329	            ? 'bg-red-50 border-red-200'
330	            : 'bg-orange-50 border-orange-200'
331	        }`}>
332	          <p className={`text-xs font-black flex items-center gap-1.5 mb-2 ${
333	            pedido.delivery_occurrence === 'cancelada' ? 'text-red-700' : 'text-orange-700'
334	          }`}>
335	            <Icon name={pedido.delivery_occurrence === 'cancelada' ? 'XCircle' : 'AlertTriangle'} size={14} />
336	            Ocorrência registrada: {pedido.delivery_occurrence === 'cancelada' ? 'Entrega cancelada' : 'Entrega pendente'}
337	          </p>
338	          <p className={`text-xs leading-relaxed ${
339	            pedido.delivery_occurrence === 'cancelada' ? 'text-red-600' : 'text-orange-600'
340	          }`}>{pedido.delivery_notes}</p>
341	        </div>
342	      )}
343	
344	      {/* Pagamento na entrega — informado pelo motoboy */}
345	      {pedido.entrega_pagamento && (
346	        <div className="bg-green-50 border border-green-200 rounded-2xl px-4 py-3 space-y-1.5">
347	          <p className="text-xs font-black text-green-700 flex items-center gap-1.5">
348	            <Icon name="CheckCircle2" size={13} /> Pagamento confirmado pelo motoboy
349	          </p>
350	          {pedido.entrega_pagamento.metodo === 'exato' && (
351	            <p className="text-sm text-green-800">Dinheiro — valor exato <strong>{fmt(pedido.entrega_pagamento.dinheiro)}</strong></p>
352	          )}
353	          {pedido.entrega_pagamento.metodo === 'conforme' && !pedido.troco_para && (
354	            <p className="text-sm text-green-800">Dinheiro — conforme pedido <strong>{fmt(pedido.entrega_pagamento.dinheiro)}</strong></p>
355	          )}
356	          {pedido.entrega_pagamento.metodo === 'conforme' && pedido.troco_para > pedido.total && (
357	            <p className="text-sm text-green-800">
358	              Dinheiro — recebeu <strong>{fmt(pedido.entrega_pagamento.dinheiro)}</strong>, deu <strong>{fmt(Number(pedido.troco_para) - Number(pedido.total))}</strong> de troco
359	            </p>
360	          )}
361	          {pedido.entrega_pagamento.metodo === 'pix' && (
362	            <p className="text-sm text-green-800">PIX — <strong>{fmt(pedido.entrega_pagamento.pix)}</strong></p>
363	          )}
364	          {pedido.entrega_pagamento.metodo === 'pix_parcial' && (
365	            <p className="text-sm text-green-800">
366	              Dinheiro <strong>{fmt(pedido.entrega_pagamento.dinheiro)}</strong> + PIX <strong>{fmt(pedido.entrega_pagamento.pix)}</strong>
367	            </p>
368	          )}
369	        </div>
370	      )}
371	
372	      {/* Comprovante PIX enviado pelo motoboy */}
373	      {pedido.comprovante_pix_url && (
374	        <div className="bg-blue-50 border border-blue-200 rounded-2xl overflow-hidden">
375	          <div className="px-4 py-3 border-b border-blue-100 flex items-center gap-2">
376	            <Icon name="Image" size={14} className="text-blue-600" />
377	            <p className="text-xs font-bold text-blue-700 uppercase tracking-wide">Comprovante PIX</p>
378	          </div>
379	          <div className="p-3">
380	            <a href={pedido.comprovante_pix_url} target="_blank" rel="noopener noreferrer">
381	              <img
382	                src={pedido.comprovante_pix_url}
383	                alt="Comprovante PIX"
384	                className="w-full rounded-xl object-contain max-h-72 border border-blue-100"
385	              />
386	            </a>
387	            <p className="text-[10px] text-blue-500 mt-1.5 text-center">Toque para ampliar</p>
388	          </div>
389	        </div>
390	      )}
391	
392	      {/* Itens */}
393	      <Section>
394	        <SectionTitle icon="ShoppingBag" label={`Itens do pedido (${itens.length})`} />
395	        <div className="p-4 space-y-2">
396	          {itens.map((item) => (
397	            <div key={item.id} className="flex items-center justify-between gap-3">
398	              <div className="flex items-center gap-2 flex-1 min-w-0">
399	                <span className="w-6 h-6 bg-[#FF441F]/10 text-[#FF441F] font-black text-xs rounded-lg flex items-center justify-center flex-shrink-0">
400	                  {item.quantity}
401	                </span>
402	                <p className="text-sm text-[#18181B] truncate">{item.product_name ?? `Produto #${item.product_id}`}</p>
403	              </div>
404	              <div className="flex-shrink-0 text-right">
405	                <p className="text-sm font-bold text-[#18181B]">{fmt(item.unit_price * item.quantity)}</p>
406	                {item.quantity > 1 && <p className="text-[10px] text-[#71717A]">{fmt(item.unit_price)} cada</p>}
407	              </div>
408	            </div>
409	          ))}
410	          {/* Frete motoboy */}
411	          <div className="flex items-center justify-between pt-2 border-t border-[#E4E4E7] mt-2">
412	            <div className="flex items-center gap-1.5">
413	              <Icon name="Truck" size={13} className="text-[#71717A]" />
414	              <span className="text-sm text-[#71717A]">Frete motoboy</span>
415	            </div>
416	            <div className="flex items-center gap-2">
417	              {pedido.frete_cobrado > 0 ? (
418	                <>
419	                  <span className="text-sm font-medium text-[#18181B]">{fmt(pedido.frete_cobrado)}</span>
420	                  {!isCanceled && pedido.status !== 'delivered' && (
421	                    <button
422	                      onClick={handleFreteGratis}
423	                      disabled={zerrandoFrete}
424	                      title="Zerar frete para este pedido"
425	                      className="text-xs px-2 py-0.5 border border-green-400 text-green-700 bg-green-50 rounded-lg hover:bg-green-100 disabled:opacity-50 transition-colors"
426	                    >
427	                      {zerrandoFrete ? '...' : 'Grátis'}
428	                    </button>
429	                  )}
430	                </>
431	              ) : (
432	                <span className="text-sm font-medium text-green-600">Grátis</span>
433	              )}
434	            </div>
435	          </div>
436	
437	          <div className="flex justify-between pt-2 border-t border-[#E4E4E7] mt-2">
438	            <span className="text-sm font-bold text-[#18181B]">Total</span>
439	            <span className="text-lg font-black text-[#FF441F]">{fmt(pedido.total)}</span>
440	          </div>
441	          {troco > 0 && (
442	            <div className="bg-amber-50 border-2 border-amber-300 rounded-xl p-3 mt-1 space-y-1">
443	              <p className="text-xs font-black text-amber-800 flex items-center gap-1.5">
444	                <Icon name="Banknote" size={13} /> ATENÇÃO — TROCO
445	              </p>
446	              <p className="text-sm text-amber-900">
447	                Pegar <strong>{fmt(pedido.troco_para)}</strong> do cliente · Dar <strong>{fmt(troco)}</strong> de troco
448	              </p>
449	            </div>
450	          )}
451	          {troco > 0 && saldoCaixa < troco && (
452	            <div className="bg-red-50 border-2 border-red-400 rounded-xl p-3 mt-1 space-y-1">
453	              <p className="text-xs font-black text-red-700 flex items-center gap-1.5">
454	                <Icon name="AlertTriangle" size={13} /> SALDO INSUFICIENTE PARA TROCO
455	              </p>
456	              <p className="text-sm text-red-800">
457	                Caixa tem <strong>{fmt(saldoCaixa)}</strong> · Precisa de <strong>{fmt(troco)}</strong> de troco.
458	              </p>
459	              <p className="text-xs text-red-600 font-semibold">
460	                Insira pelo menos <strong>{fmt(troco - saldoCaixa)}</strong> em dinheiro no caixa antes de enviar o motoboy.
461	              </p>
462	            </div>
463	          )}
464	        </div>
465	      </Section>
466	
467	      {/* Pagamento */}
468	      <Section>
469	        <div className="px-4 py-3 flex items-center gap-3">
470	          <div className="w-9 h-9 bg-[#FF441F]/10 rounded-xl flex items-center justify-center flex-shrink-0">
471	            <Icon name={pedido.payment_method === 'cash' ? 'Banknote' : pedido.payment_method === 'pix' ? 'QrCode' : 'CreditCard'} size={16} className="text-[#FF441F]" />
472	          </div>
473	          <div>
474	            <p className="text-xs text-[#71717A] font-medium">Pagamento</p>
475	            <p className="text-sm font-bold text-[#18181B]">{PAYMENT_LABELS[pedido.payment_method] ?? pedido.payment_method}</p>
476	          </div>
477	          {pedido.payment_method === 'cash' && (
478	            <span className="ml-auto text-xs font-bold text-orange-600 bg-orange-50 border border-orange-200 px-2 py-1 rounded-lg">
479	              Cobrar na entrega
480	            </span>
481	          )}
482	        </div>
483	
484	        {/* Input de troco — sempre visível para pedidos cash */}
485	        {pedido.payment_method === 'cash' && (
486	          <div className="px-4 pb-3 border-t border-[#F4F4F5] pt-3">
487	            <div className="space-y-2">
488	              <p className="text-xs text-[#71717A] font-medium">
489	                {troco > 0 ? 'Alterar valor que o cliente vai pagar:' : 'Cliente vai pagar com quanto? (opcional)'}
490	              </p>
491	              <div className="flex gap-2">
492	                <input
493	                  type="number"
494	                  step="0.01"
495	                  min={pedido.total + 0.01}
496	                  value={trocoInput}
497	                  onChange={(e) => setTrocoInput(e.target.value)}
498	                  placeholder={`Mín. ${fmt(pedido.total + 1)}`}
499	                  className="flex-1 min-w-0 border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-amber-400"
500	                />
501	                <button
502	                  onClick={handleSalvarTroco}
503	                  disabled={salvandoTroco || !trocoInput || parseFloat(trocoInput.replace(',', '.')) <= pedido.total}
504	                  className="flex-shrink-0 px-4 py-2 bg-amber-500 hover:bg-amber-600 text-white text-sm font-bold rounded-xl disabled:opacity-50 transition-colors"
505	                >
506	                  {salvandoTroco ? '...' : 'OK'}
507	                </button>
508	              </div>
509	            </div>
510	          </div>
511	        )}
512	      </Section>
513	
514	      {/* Ações */}
515	      {!isCanceled && pedido.status !== 'delivered' && (
516	        <div className="space-y-2 pb-2">
517	          {/* Cancelamento admin */}
518	          {!showCancelar ? (
519	            <button
520	              onClick={() => setShowCancelar(true)}
521	              className="w-full py-2.5 border-2 border-red-200 bg-red-50 text-red-600 text-xs font-bold rounded-2xl hover:bg-red-100 transition-colors flex items-center justify-center gap-1.5"
522	            >
523	              <Icon name="XCircle" size={14} /> Cancelar Pedido
524	            </button>
525	          ) : (
526	            <div className="bg-red-50 border-2 border-red-300 rounded-2xl p-3 space-y-2">
527	              <p className="text-xs font-bold text-red-700 flex items-center gap-1.5">
528	                <Icon name="AlertTriangle" size={13} /> Cancelar Pedido #{pedido.id}
529	              </p>
530	              <textarea
531	                value={motivoCancelamento}
532	                onChange={(e) => setMotivoCancelamento(e.target.value)}
533	                placeholder="Informe o motivo do cancelamento..."
534	                rows={2}
535	                className="w-full border border-red-300 rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-red-300 resize-none"
536	              />
537	              <div className="flex gap-2">
538	                <button
539	                  onClick={() => { setShowCancelar(false); setMotivoCancelamento(''); }}
540	                  className="flex-1 py-2 border border-red-200 text-red-500 text-xs font-semibold rounded-xl hover:bg-red-100 transition-colors"
541	                >
542	                  Voltar
543	                </button>
544	                <button
545	                  onClick={handleCancelarAdmin}
546	                  disabled={cancelando || !motivoCancelamento.trim()}
547	                  className="flex-[2] py-2 bg-red-600 hover:bg-red-700 text-white text-xs font-bold rounded-xl disabled:opacity-50 transition-colors"
548	                >
549	                  {cancelando ? 'Cancelando...' : 'Confirmar Cancelamento'}
550	                </button>
551	              </div>
552	            </div>
553	          )}
554	        </div>
555	      )}
556	
557	      {!isCanceled && pedido.status !== 'delivered' && (
558	        <div className="space-y-2 pb-2">
559	          {/* Pendente */}
560	          {pedido.status === 'pending' && proxStatus && (
561	            <button
562	              disabled={atualizando === pedido.id}
563	              onClick={() => onAvancar(pedido, proxStatus)}
564	              className="w-full py-3.5 bg-orange-500 hover:bg-orange-600 text-white text-sm font-black rounded-2xl disabled:opacity-50 transition-colors flex items-center justify-center gap-2 shadow-lg shadow-orange-200"
565	            >
566	              {atualizando === pedido.id
567	                ? 'Confirmando...'
568	                : <><Icon name="ChefHat" size={16} /> Confirmar e Enviar p/ Cozinha</>}
569	            </button>
570	          )}
571	
572	          {/* Ativo: impressão */}
573	          {['confirmed', 'preparing', 'ready', 'motoboy_collecting', 'out_for_delivery'].includes(pedido.status) && (
574	            <div className="flex gap-2">
575	              {onReimprimir && (
576	                <button
577	                  onClick={() => onReimprimir(pedido)}
578	                  className="flex-1 py-3 border-2 border-orange-300 bg-orange-50 text-orange-700 text-sm font-bold rounded-2xl hover:bg-orange-100 transition-colors flex items-center justify-center gap-2"
579	                >
580	                  <Icon name="Printer" size={15} />
581	                  Reimprimir Comanda
582	                </button>
583	              )}
584	              <button
585	                onClick={() => printFichaMotoboy(pedido, itens, cliente, null)}
586	                className="flex-1 py-3 border-2 border-indigo-200 bg-indigo-50 text-indigo-700 text-sm font-bold rounded-2xl hover:bg-indigo-100 transition-colors flex items-center justify-center gap-2"
587	              >
588	                <Icon name="Bike" size={15} />
589	                Imprimir Motoboy
590	              </button>
591	            </div>
592	          )}
593	
594	          {/* Ativo: avançar / voltar status */}
595	          {['confirmed', 'preparing', 'ready', 'motoboy_collecting', 'out_for_delivery'].includes(pedido.status) && (
596	            <div className="flex gap-2">
597	              {antStatus && (
598	                <button
599	                  disabled={atualizando === pedido.id}
600	                  onClick={() => onAvancar(pedido, antStatus)}
601	                  className="flex-1 py-2.5 border-2 border-[#E4E4E7] bg-white text-[#71717A] text-xs font-bold rounded-2xl hover:bg-[#F4F4F5] disabled:opacity-50 transition-colors flex items-center justify-center gap-1.5"
602	                >
603	                  <Icon name="ChevronLeft" size={14} /> Voltar Status
604	                </button>
605	              )}
606	              {proxStatus && (
607	                <button
608	                  disabled={atualizando === pedido.id}
609	                  onClick={() => onAvancar(pedido, proxStatus)}
610	                  className="flex-1 py-2.5 border-2 border-[#FF441F]/30 bg-[#FF441F]/5 text-[#FF441F] text-xs font-bold rounded-2xl hover:bg-[#FF441F]/10 disabled:opacity-50 transition-colors flex items-center justify-center gap-1.5"
611	                >
612	                  Avançar Status <Icon name="ChevronRight" size={14} />
613	                </button>
614	              )}
615	            </div>
616	          )}
617	        </div>
618	      )}
619	    </motion.div>
620	  );
621	};
622	
623	export default PedidoDetalhe;
