10	const PAGAMENTO_LABEL = { pix: 'PIX', credit_card: 'Cartão crédito', debit_card: 'Cartão débito', cash: 'Dinheiro' };
11	const traduzFormas = (s) => s ? s.split(' + ').map((f) => PAGAMENTO_LABEL[f] ?? f).join(' + ') : '—';
12	
13	const buildPrintHtml = (garcons, vendas, restauranteNome, label, garcomNome) => {
14	  const rows = garcons.map((g) => `<tr>
15	    <td>${g.nome}</td>
16	    <td class="right bold green">${fmt(g.total_vendido)}</td>
17	    <td class="right">${fmt(g.total_comissao)}</td>
18	    <td class="right">${fmt(g.total_gorjeta)}</td>
19	    <td class="right bold">${fmt(g.total_comissao + g.total_gorjeta)}</td>
20	    <td class="right">${g.comandas_abertas}</td>
21	    <td class="right">${g.comandas_pendentes}</td>
22	  </tr>`).join('');
23	
24	  const vendaRows = (vendas ?? []).map((v) => `<tr>
25	    <td>${dataHora(v.data)}</td>
26	    <td>${v.garcom_nome}</td>
27	    <td>${v.numero_comanda ?? '—'}${v.mesa_numero ? ` (Mesa ${v.mesa_numero})` : ''}</td>
28	    <td>${v.cliente_nome ?? '—'}</td>
29	    <td class="right">${fmt(v.total)}</td>
30	    <td class="right">${fmt(v.gorjeta)}</td>
31	    <td class="right">${fmt(v.taxa_cartao)}</td>
32	    <td>${traduzFormas(v.formas_pagamento)}</td>
33	    <td class="right bold">${fmt(v.total_geral)}</td>
34	  </tr>`).join('');
35	
36	  const vTotal = (vendas ?? []).reduce((s, v) => s + v.total, 0);
37	  const vGorjeta = (vendas ?? []).reduce((s, v) => s + v.gorjeta, 0);
38	  const vTaxaCartao = (vendas ?? []).reduce((s, v) => s + v.taxa_cartao, 0);
39	  const vTotalGeral = (vendas ?? []).reduce((s, v) => s + v.total_geral, 0);
40	  const vendaTotalRow = (vendas ?? []).length ? `<tr>
41	    <td colspan="4" class="bold">Total (${vendas.length})</td>
42	    <td class="right bold">${fmt(vTotal)}</td>
43	    <td class="right bold">${fmt(vGorjeta)}</td>
44	    <td class="right bold">${fmt(vTaxaCartao)}</td>
45	    <td></td>
46	    <td class="right bold">${fmt(vTotalGeral)}</td>
47	  </tr>` : '';
48	
49	  return `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Relatório Garçom</title>
50	<style>${reportBaseStyle}</style></head><body>
51	<h1>${restauranteNome ?? 'RESTAURANTE'}</h1>
52	<div class="sub">Relatório por Garçom${garcomNome ? ` — ${garcomNome}` : ''} — ${label}</div>
53	<table>
54	  <tr><th>Garçom</th><th class="right">Total Vendido</th><th class="right">Comissão</th><th class="right">Gorjeta</th><th class="right">Total a Receber</th><th class="right">Comandas Abertas</th><th class="right">Pendentes</th></tr>
55	  ${rows || '<tr><td colspan="7">Nenhum garçom com movimento no período.</td></tr>'}
56	</table>
57	<div class="sub" style="margin-top:16px">Detalhamento das vendas</div>
58	<table>
59	  <tr><th>Data/Hora</th><th>Garçom</th><th>Comanda/Mesa</th><th>Cliente</th><th class="right">Total</th><th class="right">Gorjeta</th><th class="right">Taxa Cartão</th><th>Pagamento</th><th class="right">Total Geral</th></tr>
60	  ${vendaRows || '<tr><td colspan="9">Nenhuma venda no período.</td></tr>'}
61	  ${vendaTotalRow}
62	</table>
63	<footer>Emitido em: ${agora()}</footer>
64	${printFooterScript}
65	</body></html>`;
66	};
67	
68	const RelatorioGarcom = () => {
69	  const [restauranteNome, setRestauranteNome] = useState('');
70	  const [filtro, setFiltro] = useState(defaultFiltroState());
71	  const [garcons, setGarcons] = useState(null);
72	  const [vendas, setVendas] = useState([]);
73	  const [label, setLabel] = useState('');
74	  const [garcomId, setGarcomId] = useState('');
75	  const [loading, setLoading] = useState(false);
76	  const [erro, setErro] = useState(null);
77	  const [rangeAtual, setRangeAtual] = useState(null);
78	  const [marcandoPago, setMarcandoPago] = useState(null);
79	  const [repasseModal, setRepasseModal] = useState(null);
80	  const [valorDinheiro, setValorDinheiro] = useState('');
81	  const [valorPix, setValorPix] = useState('');
82	
83	  useEffect(() => {
84	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
85	  }, []);
86	
87	  const buscar = async () => {
88	    const range = buildRange(filtro.modo, filtro.dia, filtro.mes, filtro.ano, filtro.periodoIni, filtro.periodoFim);
89	    if (!range) return;
90	    setLoading(true); setErro(null);
91	    try {
92	      const d = await getRelatorioGarcom(range.de, range.ate);
93	      setGarcons(d.garcons ?? []);
94	      setVendas(d.vendas ?? []);
95	      setLabel(range.label);
96	      setRangeAtual(range);
97	    } catch (e) { setErro(e.message); }
98	    finally { setLoading(false); }
99	  };
100	
101	  const abrirRepasse = (g) => {
102	    setErro(null);
103	    setRepasseModal(g);
104	    setValorDinheiro((g.total_gorjeta + g.total_comissao).toFixed(2));
105	    setValorPix('0.00');
106	  };
107	
108	  const confirmarRepasse = async () => {
109	    if (!rangeAtual || !repasseModal) return;
110	    const total = repasseModal.total_gorjeta + repasseModal.total_comissao;
111	    const vd = Number(valorDinheiro || 0);
112	    const vp = Number(valorPix || 0);
113	    if (Math.abs(vd + vp - total) > 0.01) {
114	      setErro(`Soma dos valores (${fmt(vd + vp)}) não bate com o total a repassar (${fmt(total)})`);
115	      return;
116	    }
117	    setMarcandoPago(repasseModal.garcom_id);
118	    try {
119	      await registrarRepasseGarcom(repasseModal.garcom_id, {
120	        de: rangeAtual.de,
121	        ate: rangeAtual.ate,
122	        valor_gorjeta: repasseModal.total_gorjeta,
123	        valor_comissao: repasseModal.total_comissao,
124	        valor_dinheiro: vd,
125	        valor_pix: vp,
126	      });
127	      setRepasseModal(null);
128	      await buscar();
129	    } catch (e) { setErro(e.message); }
130	    finally { setMarcandoPago(null); }
131	  };
132	
133	  const estornarRepasse = async (g) => {
134	    if (!window.confirm(`Reverter o repasse de ${g.nome} pra "não pago"? Se teve baixa em dinheiro no caixa, ela também é estornada.`)) return;
135	    setMarcandoPago(g.garcom_id);
136	    try {
137	      await estornarRepasseGarcom(g.repasse.id);
138	      await buscar();
139	    } catch (e) { setErro(e.message); }
140	    finally { setMarcandoPago(null); }
141	  };
142	
143	  useEffect(() => { buscar(); }, []); // eslint-disable-line
144	
145	  const garconsFiltrados = garcomId ? (garcons ?? []).filter((g) => String(g.garcom_id) === garcomId) : (garcons ?? []);
146	  const vendasFiltradas = garcomId ? vendas.filter((v) => String(v.garcom_id) === garcomId) : vendas;
147	  const garcomSelecionadoNome = garcomId ? (garcons ?? []).find((g) => String(g.garcom_id) === garcomId)?.nome : null;
148	
149	  const totalVendido = garconsFiltrados.reduce((s, g) => s + g.total_vendido, 0);
150	  const totalComissao = garconsFiltrados.reduce((s, g) => s + g.total_comissao, 0);
151	  const totalGorjeta = garconsFiltrados.reduce((s, g) => s + g.total_gorjeta, 0);
152	  const totalAReceber = totalComissao + totalGorjeta;
153	
154	  return (
155	    <div className="min-h-screen bg-[#FAFAFA]">
156	      <RelatorioNav titulo="Garçom" />
157	      <main className="p-6 max-w-5xl mx-auto space-y-4">
158	        <FiltroPeriodo
159	          filtro={filtro} setFiltro={setFiltro} onBuscar={buscar} loading={loading}
160	          podeImprimir={!!garcons} onImprimir={() => printIframe(buildPrintHtml(garconsFiltrados, vendasFiltradas, restauranteNome, label, garcomSelecionadoNome))}
161	        />
162	
163	        {garcons && garcons.length > 0 && (
164	          <div className="bg-white rounded-2xl border border-[#E4E4E7] p-4 flex flex-wrap gap-3 items-end">
165	            <div className="flex flex-col gap-1">
166	              <label className="text-xs font-bold text-[#71717A] uppercase tracking-widest">Garçom</label>
167	              <select value={garcomId} onChange={(e) => setGarcomId(e.target.value)}
168	                className="border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F] min-w-[200px]">
169	                <option value="">Todos os garçons</option>
170	                {garcons.map((g) => <option key={g.garcom_id} value={g.garcom_id}>{g.nome}</option>)}
171	              </select>
172	            </div>
173	            {garcomId && (
174	              <button onClick={() => printIframe(buildPrintHtml(garconsFiltrados, vendasFiltradas, restauranteNome, label, garcomSelecionadoNome))}
175	                className="flex items-center gap-2 px-4 py-2 bg-[#18181B] text-white text-sm font-bold rounded-xl hover:bg-[#27272A] transition-colors">
176	                Imprimir só {garcomSelecionadoNome}
177	              </button>
178	            )}
179	          </div>
180	        )}
181	
182	        {erro && <p className="text-sm text-red-600 bg-red-50 px-3 py-2 rounded-xl">{erro}</p>}
183	
184	        {garcons && (
185	          <>
186	            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
187	              <div className="bg-white border border-green-200 rounded-2xl p-4 text-center">
188	                <p className="text-[10px] font-black text-green-600 uppercase tracking-widest mb-1">Total Vendido</p>
189	                <p className="text-2xl font-black text-green-700">{fmt(totalVendido)}</p>
190	              </div>
191	              <div className="bg-white border border-[#E4E4E7] rounded-2xl p-4 text-center">
192	                <p className="text-[10px] font-black text-[#71717A] uppercase tracking-widest mb-1">Comissão Total</p>
193	                <p className="text-2xl font-black text-[#18181B]">{fmt(totalComissao)}</p>
194	              </div>
195	              <div className="bg-white border border-[#E4E4E7] rounded-2xl p-4 text-center">
196	                <p className="text-[10px] font-black text-[#71717A] uppercase tracking-widest mb-1">Gorjeta Total</p>
197	                <p className="text-2xl font-black text-[#18181B]">{fmt(totalGorjeta)}</p>
198	              </div>
199	              <div className="bg-white border border-[#FF441F]/30 rounded-2xl p-4 text-center">
200	                <p className="text-[10px] font-black text-[#FF441F] uppercase tracking-widest mb-1">Total a Receber</p>
201	                <p className="text-2xl font-black text-[#FF441F]">{fmt(totalAReceber)}</p>
202	              </div>
203	            </div>
204	
205	            <div className="bg-white rounded-2xl border border-[#E4E4E7] overflow-hidden">
206	              {garconsFiltrados.length === 0 ? (
207	                <p className="text-sm text-[#71717A] text-center py-10">Nenhum garçom cadastrado ou sem movimento no período.</p>
208	              ) : (
209	                <div className="overflow-x-auto">
210	                  <table className="w-full text-sm">
211	                    <thead>
212	                      <tr className="bg-[#FAFAFA] border-b border-[#F4F4F5] text-xs font-bold text-[#71717A] uppercase tracking-widest">
213	                        <th className="text-left px-5 py-3">Garçom</th>
214	                        <th className="text-right px-5 py-3">Total Vendido</th>
215	                        <th className="text-right px-5 py-3">Comissão</th>
216	                        <th className="text-right px-5 py-3">Gorjeta</th>
217	                        <th className="text-right px-5 py-3">Total a Receber</th>
218	                        <th className="text-right px-5 py-3">Comandas Abertas</th>
219	                        <th className="text-right px-5 py-3">Pendentes</th>
220	                        <th className="text-center px-5 py-3">Repasse</th>
221	                      </tr>
222	                    </thead>
223	                    <tbody className="divide-y divide-[#F4F4F5]">
224	                      {garconsFiltrados.map((g) => (
225	                        <tr key={g.garcom_id} className="hover:bg-[#FAFAFA]">
226	                          <td className="px-5 py-3 font-semibold text-[#18181B]">{g.nome}</td>
227	                          <td className="px-5 py-3 text-right font-bold text-green-700">{fmt(g.total_vendido)}</td>
228	                          <td className="px-5 py-3 text-right">{fmt(g.total_comissao)}</td>
229	                          <td className="px-5 py-3 text-right">{fmt(g.total_gorjeta)}</td>
230	                          <td className="px-5 py-3 text-right font-bold text-[#FF441F]">{fmt(g.total_comissao + g.total_gorjeta)}</td>
231	                          <td className="px-5 py-3 text-right">
232	                            {g.comandas_abertas > 0
233	                              ? <span className="px-2 py-0.5 rounded-full text-xs font-bold bg-blue-100 text-blue-800">{g.comandas_abertas}</span>
234	                              : <span className="text-[#A1A1AA]">0</span>}
235	                          </td>
236	                          <td className="px-5 py-3 text-right">
237	                            {g.comandas_pendentes > 0
238	                              ? <span className="px-2 py-0.5 rounded-full text-xs font-bold bg-amber-100 text-amber-800">{g.comandas_pendentes}</span>
239	                              : <span className="text-[#A1A1AA]">0</span>}
240	                          </td>
241	                          <td className="px-5 py-3 text-center">
242	                            {g.repasse ? (
243	                              <div className="inline-flex items-center gap-1.5">
244	                                <span className="inline-flex items-center gap-1 text-xs font-bold text-green-700" title={`Pago em ${dataHora(g.repasse.pago_em)}`}>
245	                                  ✓ Pago em {dataHora(g.repasse.pago_em)}
246	                                </span>
247	                                <button onClick={() => estornarRepasse(g)} disabled={marcandoPago === g.garcom_id}
248	                                  title="Reverter pra não pago (corrigir lançamento)"
249	                                  className="w-5 h-5 rounded-md border border-zinc-300 bg-zinc-50 text-zinc-500 flex items-center justify-center hover:bg-zinc-100 disabled:opacity-50 flex-shrink-0">
250	                                  ↺
251	                                </button>
252	                              </div>
253	                            ) : (g.total_comissao + g.total_gorjeta) > 0 ? (
254	                              <button onClick={() => abrirRepasse(g)} disabled={marcandoPago === g.garcom_id}
255	                                className="px-3 py-1.5 bg-[#18181B] text-white text-xs font-bold rounded-lg hover:bg-[#27272A] disabled:opacity-50">
256	                                Pagar
257	                              </button>
258	                            ) : <span className="text-[#A1A1AA]">—</span>}
259	                          </td>
260	                        </tr>
261	                      ))}
262	                    </tbody>
263	                  </table>
264	                </div>
265	              )}
266	            </div>
267	
268	            <div className="bg-white rounded-2xl border border-[#E4E4E7] overflow-hidden">
269	              <div className="px-5 py-3 border-b border-[#F4F4F5]">
270	                <h2 className="text-sm font-black text-[#18181B]">Detalhamento das Vendas</h2>
271	                <p className="text-xs text-[#71717A]">Comanda a comanda, para conferência</p>
272	              </div>
273	              {vendasFiltradas.length === 0 ? (
274	                <p className="text-sm text-[#71717A] text-center py-10">Nenhuma venda no período.</p>
275	              ) : (
276	                <div className="overflow-x-auto">
277	                  <table className="w-full text-sm">
278	                    <thead>
279	                      <tr className="bg-[#FAFAFA] border-b border-[#F4F4F5] text-xs font-bold text-[#71717A] uppercase tracking-widest">
280	                        <th className="text-left px-5 py-3">Data/Hora</th>
281	                        <th className="text-left px-5 py-3">Garçom</th>
282	                        <th className="text-left px-5 py-3">Comanda/Mesa</th>
283	                        <th className="text-left px-5 py-3">Cliente</th>
284	                        <th className="text-right px-5 py-3">Total</th>
285	                        <th className="text-right px-5 py-3">Gorjeta</th>
286	                        <th className="text-right px-5 py-3">Taxa Cartão</th>
287	                        <th className="text-left px-5 py-3">Pagamento</th>
288	                        <th className="text-right px-5 py-3">Total Geral</th>
289	                      </tr>
290	                    </thead>
291	                    <tbody className="divide-y divide-[#F4F4F5]">
292	                      {vendasFiltradas.map((v) => (
293	                        <tr key={v.order_id} className="hover:bg-[#FAFAFA]">
294	                          <td className="px-5 py-3 whitespace-nowrap text-[#71717A]">{dataHora(v.data)}</td>
295	                          <td className="px-5 py-3 font-semibold text-[#18181B]">{v.garcom_nome}</td>
296	                          <td className="px-5 py-3 whitespace-nowrap">
297	                            {v.numero_comanda ?? '—'}{v.mesa_numero ? ` (Mesa ${v.mesa_numero})` : ''}
298	                          </td>
299	                          <td className="px-5 py-3">{v.cliente_nome ?? '—'}</td>
300	                          <td className="px-5 py-3 text-right">{fmt(v.total)}</td>
301	                          <td className="px-5 py-3 text-right">{fmt(v.gorjeta)}</td>
302	                          <td className="px-5 py-3 text-right">{fmt(v.taxa_cartao)}</td>
303	                          <td className="px-5 py-3">{traduzFormas(v.formas_pagamento)}</td>
304	                          <td className="px-5 py-3 text-right font-bold text-[#FF441F]">{fmt(v.total_geral)}</td>
305	                        </tr>
306	                      ))}
307	                    </tbody>
308	                    <tfoot>
309	                      <tr className="bg-[#FAFAFA] border-t-2 border-[#E4E4E7] font-bold">
310	                        <td colSpan={4} className="px-5 py-3 text-[#18181B]">Total ({vendasFiltradas.length})</td>
311	                        <td className="px-5 py-3 text-right">{fmt(vendasFiltradas.reduce((s, v) => s + v.total, 0))}</td>
312	                        <td className="px-5 py-3 text-right">{fmt(vendasFiltradas.reduce((s, v) => s + v.gorjeta, 0))}</td>
313	                        <td className="px-5 py-3 text-right">{fmt(vendasFiltradas.reduce((s, v) => s + v.taxa_cartao, 0))}</td>
314	                        <td className="px-5 py-3"></td>
315	                        <td className="px-5 py-3 text-right text-[#FF441F]">{fmt(vendasFiltradas.reduce((s, v) => s + v.total_geral, 0))}</td>
316	                      </tr>
317	                    </tfoot>
318	                  </table>
319	                </div>
320	              )}
321	            </div>
322	          </>
323	        )}
324	      </main>
325	
326	      {repasseModal && (
327	        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
328	          <div className="bg-white rounded-2xl p-6 w-full max-w-sm shadow-2xl">
329	            <h2 className="text-base font-bold text-[#18181B] mb-1">Pagar {repasseModal.nome}</h2>
330	            <p className="text-xs text-[#71717A] mb-4">
331	              Total a repassar: <span className="font-bold">{fmt(repasseModal.total_gorjeta + repasseModal.total_comissao)}</span>
332	              {' '}(gorjeta {fmt(repasseModal.total_gorjeta)} + comissão {fmt(repasseModal.total_comissao)})
333	            </p>
334	            <div className="space-y-3">
335	              <div className="flex gap-2">
336	                <div className="flex-1">
337	                  <label className="block text-xs font-medium text-[#71717A] mb-1">Dinheiro (R$)</label>
338	                  <input
339	                    type="number" min="0" step="0.01"
340	                    value={valorDinheiro}
341	                    onChange={(e) => setValorDinheiro(e.target.value)}
342	                    className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]"
343	                  />
344	                </div>
345	                <div className="flex-1">
346	                  <label className="block text-xs font-medium text-[#71717A] mb-1">PIX (R$)</label>
347	                  <input
348	                    type="number" min="0" step="0.01"
349	                    value={valorPix}
350	                    onChange={(e) => setValorPix(e.target.value)}
351	                    className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]"
352	                  />
353	                </div>
354	              </div>
355	              <p className="text-[11px] text-[#71717A]">Valor em dinheiro dá baixa automática no caixa aberto (sangria). PIX não mexe no caixa.</p>
356	              {erro && <p className="text-xs text-red-600 bg-red-50 px-3 py-2 rounded-xl">{erro}</p>}
357	              <div className="flex gap-2 pt-1">
358	                <button type="button" onClick={() => { setRepasseModal(null); setErro(null); }}
359	                  className="flex-1 py-2 text-sm border border-[#E4E4E7] rounded-xl text-[#71717A] hover:bg-[#F4F4F5]">
360	                  Cancelar
361	                </button>
362	                <button type="button" onClick={confirmarRepasse} disabled={marcandoPago === repasseModal.garcom_id}
363	                  className="flex-1 py-2 text-sm bg-[#FF441F] text-white rounded-xl font-semibold hover:bg-[#E63A19] disabled:opacity-50">
364	                  {marcandoPago === repasseModal.garcom_id ? 'Confirmando...' : 'Confirmar'}
365	                </button>
366	              </div>
367	            </div>
368	          </div>
369	        </div>
370	      )}
371	    </div>
372	  );
373	};
374	
375	export default RelatorioGarcom;
