                </span>
              </td>
              <td className="px-5 py-3 text-right text-[#71717A]">{p.quantidade_minima ?? 0}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  </div>
);

export default RelatorioProdutos;

