    const produtos = (produtosData ?? []).map((p: any) => ({ ...p, category_name: p.categories?.name ?? 'Outros' }));

    const { data: orders } = await this.supabase.client
      .from('orders')
      .select('id')
      .eq('restaurant_id', restaurantId)
      .gte('created_at', de)
      .lte('created_at', ate)
      .in('status', this.STATUS_VENDA_FINALIZADA);

    const orderIds = (orders ?? []).map((o: any) => o.id);
    const vendasPorProduto = new Map<number, { quantidade: number; receita: number }>();
    if (orderIds.length) {
      const { data: items } = await this.supabase.client
        .from('order_items')
        .select('product_id, quantity, unit_price')
        .in('order_id', orderIds);
      for (const i of (items ?? []) as any[]) {
        if (!vendasPorProduto.has(i.product_id)) vendasPorProduto.set(i.product_id, { quantidade: 0, receita: 0 });
        const row = vendasPorProduto.get(i.product_id)!;
        row.quantidade += i.quantity ?? 0;
        row.receita += (i.quantity ?? 0) * (i.unit_price ?? 0);
      }
    }

    const vendas = produtos
      .map((p: any) => {
        const quantidade_vendida = vendasPorProduto.get(p.id)?.quantidade ?? 0;
        const receita = vendasPorProduto.get(p.id)?.receita ?? 0;
        const custo_total = quantidade_vendida * (p.preco_custo ?? 0);
        return {
          product_id: p.id,
          name: p.name,
          quantidade_vendida,
          receita,
          custo_total,
          lucro: receita - custo_total,
        };
      })
      .sort((a: any, b: any) => b.receita - a.receita);

    const lucro_total = vendas.reduce((acc: number, v: any) => acc + v.lucro, 0);
    const receita_total = vendas.reduce((acc: number, v: any) => acc + v.receita, 0);

    return {
      produtos,
      sem_estoque: produtos.filter((p: any) => (p.quantidade_estoque ?? 0) <= 0),
      reposicao: produtos.filter((p: any) => (p.quantidade_estoque ?? 0) <= (p.quantidade_minima ?? 0)),
      sem_giro: vendas.filter((v: any) => v.quantidade_vendida === 0),
      ativos: produtos.filter((p: any) => p.is_active),
      bloqueados: produtos.filter((p: any) => !p.is_active),
      vendas,
      lucro_total,
      receita_total,
    };
  }

  async buscarPedidoDoRestaurante(restaurantId: number, pedidoId: number) {
    const resultado = await this.pedidos.buscar(pedidoId);
    if (resultado.pedido.restaurant_id !== restaurantId) {
      throw new NotFoundException('Pedido não encontrado neste restaurante');
    }

    if (resultado.itens.length > 0) {
      const prodIds = resultado.itens.map((i: any) => i.product_id);
      const { data: produtos } = await this.supabase.client
        .from('products')
        .select('id, name')
        .in('id', prodIds);
      const prodMap = Object.fromEntries((produtos ?? []).map((p: any) => [p.id, p.name]));
      resultado.itens = resultado.itens.map((i: any) => ({
        ...i,
        product_name: prodMap[i.product_id] ?? `Produto #${i.product_id}`,
      }));
    }

    return resultado;
  }
}

