1	import React, { useState, useEffect } from 'react';
2	import { getRelatorioProdutos, getMinhaEmpresa } from '../../services/restauranteService';
3	import RelatorioNav from './RelatorioNav';
4	import FiltroPeriodo from './FiltroPeriodo';
5	import { fmt, buildRange, printIframe, reportBaseStyle, printFooterScript, defaultFiltroState } from '../../utils/relatorioPrint';
6	
7	const ABAS = [
8	  { id: 'todos', label: 'Lista' },
9	  { id: 'sem_estoque', label: 'Sem Estoque' },
10	  { id: 'reposicao', label: 'Reposição' },
11	  { id: 'status', label: 'Ativos / Bloqueados' },
12	  { id: 'vendas', label: 'Vendas no Período' },
13	  { id: 'sem_giro', label: 'Sem Giro' },
14	  { id: 'lucro', label: 'Lucro no Período' },
15	];
16	
17	const QTD_FILTRO_INICIAL = { modo: 'todos', valor: '' };
18	
19	const aplicarFiltroQtd = (lista, campo, filtro) => {
20	  if (!filtro || filtro.modo === 'todos') return lista;
21	  if (filtro.modo === 'zero') return lista.filter((x) => (x[campo] ?? 0) === 0);
22	  if (filtro.modo === 'valor') {
23	    if (filtro.valor === '' || filtro.valor == null) return lista;
24	    const v = Number(filtro.valor);
25	    return lista.filter((x) => (x[campo] ?? 0) <= v);
26	  }
27	  return lista;
28	};
29	
30	const QtdFiltroBar = ({ filtro, onChange, labelZero }) => (
31	  <div className="flex items-center gap-2 flex-wrap">
32	    <div className="flex gap-1 bg-[#F4F4F5] dark:bg-[#3F3F46] p-1 rounded-xl w-fit">
33	      {[{ id: 'todos', label: 'Todos' }, { id: 'zero', label: labelZero }, { id: 'valor', label: 'Valor' }].map((o) => (
34	        <button key={o.id} onClick={() => onChange({ ...filtro, modo: o.id })}
35	          className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-colors ${filtro.modo === o.id ? 'bg-white dark:bg-[#27272A] text-[#18181B] dark:text-[#F4F4F5] shadow-sm' : 'text-[#71717A] dark:text-[#A1A1AA] hover:text-[#27272A] dark:hover:text-[#F4F4F5]'}`}>
36	          {o.label}
37	        </button>
38	      ))}
39	    </div>
40	    {filtro.modo === 'valor' && (
41	      <input
42	        type="number" min="0" step="1"
43	        value={filtro.valor}
44	        onChange={(e) => onChange({ ...filtro, valor: e.target.value })}
45	        placeholder="Até quantidade..."
46	        className="border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-lg px-3 py-1.5 text-xs w-36"
47	      />
48	    )}
49	  </div>
50	);
51	
52	const buildPrintHtml = (dados, aba, restauranteNome, label, listaOverride) => {
53	  const listaAtual = listaOverride ?? (aba === 'sem_estoque' ? dados.sem_estoque
54	    : aba === 'reposicao' ? dados.reposicao
55	    : aba === 'vendas' ? dados.vendas
56	    : aba === 'sem_giro' ? dados.sem_giro
57	    : aba === 'lucro' ? dados.vendas
58	    : dados.produtos);
59	
60	  const rows = aba === 'vendas' || aba === 'sem_giro'
61	    ? listaAtual.map((p) => `<tr><td>${p.name}</td><td class="right">${p.quantidade_vendida}</td><td class="right bold green">${fmt(p.receita)}</td></tr>`).join('')
62	    : aba === 'lucro'
63	    ? listaAtual.map((p) => `<tr><td>${p.name}</td><td class="right">${p.quantidade_vendida}</td><td class="right">${fmt(p.receita)}</td><td class="right">${fmt(p.custo_total)}</td><td class="right bold green">${fmt(p.lucro)}</td></tr>`).join('')
64	    : aba === 'reposicao'
65	    ? listaAtual.map((p) => `<tr><td>${p.name}</td><td>${p.category_name}</td><td class="right">${p.quantidade_estoque}</td><td class="right">${p.quantidade_minima}</td></tr>`).join('')
66	    : listaAtual.map((p) => `<tr><td>${p.name}</td><td>${p.category_name}</td><td class="right">${fmt(p.price)}</td><td class="right">${p.quantidade_estoque}</td><td>${p.is_active ? 'Ativo' : 'Bloqueado'}</td></tr>`).join('');
67	
68	  const header = aba === 'vendas' || aba === 'sem_giro'
69	    ? '<tr><th>Produto</th><th class="right">Qtd Vendida</th><th class="right">Receita</th></tr>'
70	    : aba === 'lucro'
71	    ? '<tr><th>Produto</th><th class="right">Qtd Vendida</th><th class="right">Receita</th><th class="right">Custo</th><th class="right">Lucro</th></tr>'
72	    : aba === 'reposicao'
73	    ? '<tr><th>Produto</th><th>Categoria</th><th class="right">Estoque</th><th class="right">Mínimo</th></tr>'
74	    : '<tr><th>Produto</th><th>Categoria</th><th class="right">Preço</th><th class="right">Estoque</th><th>Status</th></tr>';
75	
76	  return `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Relatório Produtos</title>
77	<style>${reportBaseStyle}</style></head><body>
78	<h1>${restauranteNome ?? 'RESTAURANTE'}</h1>
79	<div class="sub">Relatório de Produtos — ${ABAS.find((a) => a.id === aba)?.label} ${aba === 'vendas' ? `— ${label}` : ''}</div>
80	<table>${header}${rows || '<tr><td colspan="5">Nenhum produto encontrado.</td></tr>'}</table>
81	<footer>Emitido em: ${new Date().toLocaleString('pt-BR')}</footer>
82	${printFooterScript}
83	</body></html>`;
84	};
85	
86	const RelatorioProdutos = () => {
87	  const [restauranteNome, setRestauranteNome] = useState('');
88	  const [filtro, setFiltro] = useState(defaultFiltroState());
89	  const [dados, setDados] = useState(null);
90	  const [label, setLabel] = useState('');
91	  const [loading, setLoading] = useState(false);
92	  const [erro, setErro] = useState(null);
93	  const [aba, setAba] = useState('todos');
94	  const [statusFiltro, setStatusFiltro] = useState('todos');
95	  const [repFiltro, setRepFiltro] = useState('minimo');
96	  const [qtdFiltroLista, setQtdFiltroLista] = useState(QTD_FILTRO_INICIAL);
97	  const [qtdFiltroSemEstoque, setQtdFiltroSemEstoque] = useState({ modo: 'zero', valor: '' });
98	  const [qtdFiltroSemGiro, setQtdFiltroSemGiro] = useState({ modo: 'zero', valor: '' });
99	  const [qtdFiltroLucro, setQtdFiltroLucro] = useState(QTD_FILTRO_INICIAL);
100	  const [qtdFiltroVendas, setQtdFiltroVendas] = useState(QTD_FILTRO_INICIAL);
101	
102	  useEffect(() => {
103	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
104	  }, []);
105	
106	  const buscar = async () => {
107	    const range = buildRange(filtro.modo, filtro.dia, filtro.mes, filtro.ano, filtro.periodoIni, filtro.periodoFim);
108	    if (!range) return;
109	    setLoading(true); setErro(null);
110	    try {
111	      const d = await getRelatorioProdutos(range.de, range.ate);
112	      setDados(d);
113	      setLabel(range.label);
114	    } catch (e) { setErro(e.message); }
115	    finally { setLoading(false); }
116	  };
117	
118	  useEffect(() => { buscar(); }, []); // eslint-disable-line
119	
120	  const exportarJson = () => {
121	    if (!dados) return;
122	    const lista = dados.produtos.map((p) => ({
123	      id: p.id,
124	      nome: p.name,
125	      categoria: p.category_name,
126	      preco: p.price,
127	      preco_custo: p.preco_custo,
128	      quantidade_estoque: p.quantidade_estoque,
129	      quantidade_minima: p.quantidade_minima,
130	      ativo: p.is_active,
131	    }));
132	    const blob = new Blob([JSON.stringify(lista, null, 2)], { type: 'application/json' });
133	    const url = URL.createObjectURL(blob);
134	    const a = document.createElement('a');
135	    a.href = url;
136	    a.download = `produtos_${(restauranteNome || 'restaurante').toLowerCase().replace(/\s+/g, '-')}_${new Date().toISOString().slice(0, 10)}.json`;
137	    a.click();
138	    URL.revokeObjectURL(url);
139	  };
140	
141	  const listaStatus = dados
142	    ? statusFiltro === 'ativos' ? dados.ativos
143	    : statusFiltro === 'bloqueados' ? dados.bloqueados
144	    : dados.produtos
145	    : [];
146	
147	  const listaReposicao = dados
148	    ? repFiltro === 'geral' ? dados.produtos
149	    : dados.reposicao
150	    : [];
151	
152	  const listaLista = dados ? aplicarFiltroQtd(dados.produtos, 'quantidade_estoque', qtdFiltroLista) : [];
153	  const listaSemEstoque = dados ? aplicarFiltroQtd(dados.produtos, 'quantidade_estoque', qtdFiltroSemEstoque) : [];
154	  const listaSemGiro = dados ? aplicarFiltroQtd(dados.vendas, 'quantidade_vendida', qtdFiltroSemGiro) : [];
155	  const listaLucro = dados ? aplicarFiltroQtd(dados.vendas, 'quantidade_vendida', qtdFiltroLucro) : [];
156	  const listaVendas = dados ? aplicarFiltroQtd(dados.vendas, 'quantidade_vendida', qtdFiltroVendas) : [];
157	
158	  return (
159	    <div className="min-h-screen bg-[#FAFAFA] dark:bg-[#18181B]">
160	      <RelatorioNav titulo="Produtos" />
161	      <main className="p-6 max-w-5xl mx-auto space-y-4">
162	        <FiltroPeriodo
163	          filtro={filtro} setFiltro={setFiltro} onBuscar={buscar} loading={loading}
164	          podeExportar={!!dados} onExportarJson={exportarJson}
165	          podeImprimir={!!dados} onImprimir={() => printIframe(buildPrintHtml(dados, aba, restauranteNome, label,
166	            aba === 'todos' ? listaLista
167	            : aba === 'sem_estoque' ? listaSemEstoque
168	            : aba === 'reposicao' ? listaReposicao
169	            : aba === 'vendas' ? listaVendas
170	            : aba === 'sem_giro' ? listaSemGiro
171	            : aba === 'lucro' ? listaLucro
